// Comparação técnica (#/comparar/tecnico) — design V3ComparePlan (Planejamento kit):
// editable rules (assumptions), full metric table with margins and origin, exports and a reproducible link.
// Source of truth: this .tsx file (Preact). tecnico.js is generated by `npm --prefix web run build:ts`.
import { h, Fragment } from "../../vendor/preact/preact.module.js";
import { num } from "../../ds/components.js";
import { buildHash, type RouteCtx } from "../../ds/router.js";
import { Badge, mount } from "../../ds/ui.js";
import { hourlyRows } from "../data.js";
import { METRICS, RULE_DEFAULTS, rulesToQuery, type Rules } from "../compare.js";
import { loadComparison, SitePickers, fmtMetric } from "./comparar.js";
import { ContextBar, LETTERS, isoHour, download, setQuery } from "./common.js";

const short = (n: string) => n.replace(/\s*\(.*\)$/, "");

export async function render(outlet: HTMLElement, ctx: RouteCtx): Promise<void> {
  const { sc, entries, rules, result, live } = await loadComparison(ctx);
  const { rows } = result;

  // editable rules — premissas, never mission requirements
  const field = (key: keyof Rules, label: string, unit: string) => <label class="fld"><span class="lbl-s">{label + " (" + unit + ")"}</span>
    <input type="number" min="0" step="1" name={key} defaultValue={String(rules[key])} inputMode="numeric" />
    <small class="t3">{"padrão do protótipo: " + RULE_DEFAULTS[key]}</small></label>;
  const onRules = (e: Event) => {
    e.preventDefault();
    const fd = new FormData(e.currentTarget as HTMLFormElement), r = {} as Rules;
    for (const k of Object.keys(RULE_DEFAULTS) as (keyof Rules)[]) r[k] = Number(fd.get(k));
    setQuery(ctx, rulesToQuery(r));
  };

  const passport = () => ({
    schema: "moonproof.passport.v1",
    generated_utc: new Date().toISOString(),
    link: location.href,
    window: { start_utc: isoHour(sc.t0), days: sc.days, step_minutes: 60 },
    rules: { ...rules, note: "prototype assumptions, not mission requirements" },
    sites: rows.map((r, i) => ({
      letter: LETTERS[i], id: r.id, name: r.name, lat: r.site.lat, lon: r.site.lon, source: r.site.source,
      metrics: r.computed ? Object.fromEntries(METRICS.map(m => [m.key, (r.w as never as Record<string, number>)[m.key]])) : null, battery_margin: "N/D",
      passes_all_rules: r.computed ? r.passAll : null,
      metrics_origin: live ? "POST /api/compare" : "static series", request_sha256: r.w?.request_sha256 || null,
      series_sha256: live ? r.w.series_sha256 : r.series ? r.series.meta.series.sha256 : null, science_status: live ? r.w.science_status : r.series ? r.series.meta.science_status : null,
      provenance: live ? r.w.provenance : r.series ? r.series.meta.provenance : null,
    })),
    disclaimer: "Preliminary, not NASA-reviewed. No flight recommendation.",
  });
  const mval = (r: (typeof rows)[number], key: string) => (r.w as never as Record<string, number>)[key];

  mount(outlet, <>
    <div class="page-head">
      <div><p class="lbl-s">Kit Planejamento</p><h1 data-route-title="">Comparação técnica</h1></div>
      <ContextBar ctx={ctx} sc={sc} siteSelect={false} />
    </div>
    <p class="t3 small" role="status">{live ? "API Go ao vivo · métricas preliminares" : "API indisponível para esta janela · métricas da série estática versionada"}</p>
    <SitePickers ctx={ctx} sc={sc} entries={entries} />
    <form class="solid card rules" aria-labelledby="rules-t" onSubmit={onRules}>
      <h2 class="h-card" id="rules-t">Regras (premissas editáveis)</h2>
      <div class="cards3">{field("maxNightH", "Noite máxima", "h")}{field("maxEarthLossH", "Perda máxima da Terra", "h")}{field("minSunPct", "Sol visível mínimo", "%")}</div>
      <p class="t3 small">Altura do mastro, declividade e piso de bateria: N/D nesta versão (não calculados para as séries reais).</p>
      <div class="row wrap"><button type="submit" class="btnA">Recalcular</button>
        <button type="button" class="btnG" onClick={() => setQuery(ctx, rulesToQuery(RULE_DEFAULTS))}>Voltar ao padrão</button></div>
    </form>
    <section class="solid card tablewrap"><h2 class="h-card">Todas as métricas</h2>
      <table class="mtab">
        <caption class="sr">{"Métricas por local na janela de " + sc.days + " dias"}</caption>
        <thead><tr><th scope="col">Métrica</th><th scope="col">Unid.</th>
          {rows.map((r, i) => <th scope="col">{LETTERS[i] + " · " + short(r.name)}</th>)}
          <th scope="col">Regra</th><th scope="col">{"Margem (" + LETTERS.slice(0, rows.length).join(" / ") + ")"}</th><th scope="col">Origem</th></tr></thead>
        <tbody>
          {METRICS.map(m => <tr><th scope="row">{m.label}</th><td>{m.unit}</td>
            {rows.map(r => <td class="num">{r.computed ? fmtMetric(mval(r, m.key), m.unit) : "N/D"}</td>)}
            <td>{m.rule ? m.text!(rules) : "—"}</td>
            <td class="num">{m.rule ? rows.map(r => { const c = r.checks.find(x => x.key === m.key); return c && Number.isFinite(c.margin) ? (c.margin >= 0 ? "+" : "") + num(c.margin, 0) : "N/D"; }).join(" / ") : "—"}</td>
            <td><Badge kind="est" />{live ? " Go API · LOLA + SPICE" : " série estática · LOLA + SPICE"}</td></tr>)}
          <tr><th scope="row">Folga da bateria</th><td>Wh</td>{rows.map(() => <td>N/D</td>)}<td>—</td><td>N/D</td><td><Badge kind="nd" /> não calculado</td></tr>
          <tr><th scope="row">Altura do relevo</th><td>m</td>{rows.map(r => <td class="num">{num(r.site.site_height_m, 0)}</td>)}<td>—</td><td>—</td><td><Badge kind="est" /> LOLA LDEM_80S_80M</td></tr>
        </tbody>
      </table>
      <p class="t3 small">Margem = folga até a regra (positivo atende). Valores da série horária LOLA + SPICE, prévios e não revisados pela NASA.</p>
    </section>
    <section class="solid card"><h2 class="h-card">Exportar e reproduzir</h2>
      <div class="row wrap">
        <button type="button" class="btnG" onClick={() => {
          const lines = ["site,utc,sun_az_deg,sun_el_deg,sun_margin_deg,earth_az_deg,earth_el_deg,earth_margin_deg"];
          for (const r of rows) if (r.series) for (const row of hourlyRows(r.series, sc.t0, sc.hours)) lines.push(r.id + "," + row.map(x => (typeof x === "number" ? x.toFixed(3) : x)).join(","));
          download("moonproof_" + isoHour(sc.t0).slice(0, 10) + "_" + sc.days + "d.csv", lines.join("\n"), "text/csv");
        }}>CSV horário (série estática)</button>
        <button type="button" class="btnG" onClick={() => download("moonproof_comparacao.json", JSON.stringify({ rules, rows: rows.map(r => ({ id: r.id, w: r.w, checks: r.checks, passAll: r.passAll })) }, null, 2), "application/json")}>JSON</button>
        <button type="button" class="btnG" onClick={() => download("moonproof_passaporte.json", JSON.stringify(passport(), null, 2), "application/json")}>Passaporte</button>
      </div>
      <label class="fld share"><span class="lbl-s">Link reproduzível</span>
        <input type="text" readOnly defaultValue={location.href} onFocus={e => (e.target as HTMLInputElement).select()} /></label>
      <button type="button" class="btnL" onClick={async e => {
        const b = e.currentTarget as HTMLButtonElement;
        try { await navigator.clipboard.writeText(location.href); b.textContent = "Link copiado"; } catch { b.textContent = "Copie o link acima"; }
      }}>Copiar link</button>
    </section>
    <a class="chipg" href={buildHash("/comparar", ctx.query)}>← Voltar à resposta direta</a>
  </>);
}
